function tree(x,z,s=1){const g=new THREE.Group();g.position.set(x,0,z);const trunk=new THREE.Mesh(new THREE.CylinderGeometry(.22*s,.34*s,2.6*s,7),M.wood);trunk.position.y=1.3*s;trunk.castShadow=true;g.add(trunk);for(let i=0;i<4;i++){const f=new THREE.Mesh(new THREE.IcosahedronGeometry((1.1-i*.1)*s,1),mat(i%2?0x52734c:0x416548));f.position.set((Math.random()-.5)*.8*s,2.5*s+i*.55*s,(Math.random()-.5)*.8*s);f.castShadow=true;g.add(f)}scene.add(g);return g}
