function resetMap(){for(const o of [...group.children])group.remove(o);for(const o of [...scene.children])if(o.userData.mapItem)scene.remove(o);map=$('#mapSelect').value;const old=scene.fog;scene.background.set(map==='island'?0x9bb9bb:map==='yard'?0xb4a58c:0x829890);scene.fog=new THREE.Fog(scene.background,55,180);if(map==='island')addMansion();else addOtherMap();for(let i=0;i<35;i++){let x=(Math.random()-.5)*82,z=(Math.random()-.5)*82;if(Math.hypot(x,z)>25)tree(x,z,.65+Math.random()*.55)}}
