function makeCharacter(type,pos){const g=new THREE.Group();g.position.copy(pos);g.userData={type,hp:type==='zombie'?100:110,alive:true,ragdoll:false,parts:[],speed:type==='zombie'?1.5:0,walk:Math.random()*6};const frontier=type==='frontier',police=type==='police',zombie=type==='zombie';const skin=mat(frontier?0x65402f:police?0xc99d78:zombie?0x789078:0xb98d6a),cloth=mat(frontier?0x9a7046:police?0x273b4d:zombie?0x535f4c:0x69716a),pants=mat(frontier?0x343b36:police?0x263344:zombie?0x393e35:0x3e4843);g.userData.materials={skin,cloth,pants};
const torso=box(g,0,1.22,0,.72,.92,.4,cloth);torso.userData.part='torso';const head=new THREE.Mesh(new THREE.SphereGeometry(.28,12,10),skin);head.position.set(0,1.95,0);head.castShadow=true;head.userData.part='head';g.add(head);box(g,0,1.61,0,.22,.12,.25,skin);
const limbs=[];for(const side of [-1,1]){const leg=new THREE.Group();leg.position.set(side*.2,.78,0);g.add(leg);box(leg,0,-.31,0,.24,.68,.28,pants).userData.part='leg';box(leg,0,-.66,.08,.28,.16,.42,M.dark).userData.part='leg';limbs.push(leg);const arm=new THREE.Group();arm.position.set(side*.48,1.46,0);g.add(arm);box(arm,0,-.31,0,.22,.66,.24,cloth).userData.part='arm';box(arm,0,-.67,0,.2,.16,.2,skin).userData.part='arm';limbs.push(arm)}g.userData.limbs=limbs;
if(frontier){const band=box(g,0,2.13,0,.59,.12,.59,mat([0xa33934,0xd4a638,0x387c91,0x6d4d91][Math.floor(Math.random()*4)]));band.userData.part='bandana';box(g,0,1.3,-.25,.78,.28,.08,mat(0x684d34))}if(police){box(g,0,1.22,.22,.16,.22,.08,M.yellow);const equip=Math.random()<.5?'pistol':'shotgun';g.userData.gear=equip;makeWeaponMesh(g,equip,.3,1.35,.23)}if(zombie){const gash=box(g,.11,1.87,.23,.14,.05,.03,M.blood);gash.rotation.z=-.4;box(g,-.13,1.15,.22,.19,.12,.05,M.blood)}
if(!frontier&&!police&&!zombie)box(g,0,1.23,.23,.13,.2,.07,M.white);g.userData.limbs=limbs;g.userData.head=head;g.userData.torso=torso;group.add(g);npcs.push(g);return g}
function makeWeaponMesh(parent,type,x,y,z){const g=new THREE.Group();g.position.set(x,y,z);const shotgun=type==='shotgun';box(g,0,0,0,shotgun?.12:.23,.12,shotgun?.72:.3,M.metal);box(g,0,-.11,.02,.1,.22,.14,M.dark);parent.add(g);return g}

function addPickup(x,z,type){const g=new THREE.Group();g.position.set(x,.55,z);const color=type==='shotgun'?0xd2bd6d:type==='bat'?0x9b6b42:0x9cb6ad;const body=box(g,0,0,0,type==='shotgun'?.14:.24,.12,type==='shotgun'?.85:.32,mat(color,.35,.4));if(type==='pistol')box(g,0,-.12,.03,.1,.2,.13,M.dark);g.userData={pickup:true,type,phase:Math.random()*6};scene.add(g);props.push(g)}
addPickup(-5,5,'pistol');addPickup(6,3,'shotgun');addPickup(3,-2,'bat');
function makeZombieWave(n=5){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,r=14+Math.random()*12;makeCharacter('zombie',new THREE.Vector3(Math.cos(a)*r,0,Math.sin(a)*r))}}
function setMode(m){mode=m;$('#modeRead').textContent=m.toUpperCase();$('#spawnBtn').disabled=m==='arena';$('#spawnBtn').style.opacity=m==='arena'?'.35':'1';if(m==='arena'){npcs.splice(0,npcs.length,...npcs.filter(n=>{group.remove(n);return false}));makeZombieWave(7);toast('Arena live · zombies incoming')}else{npcs.forEach(n=>group.remove(n));npcs.length=0;health=100}}
const types=[['frontier','Frontier survivor','Dark skin · bandana'],['police','Police officer','50/50 sidearm or shotgun'],['civilian','Civilian','Everyday field clothes'],['zombie','Zombie','Unsteady, aggressive']];
for(const [id,title,sub] of types){const b=document.createElement('button');b.className='choice'+(id===selectedType?' selected':'');b.innerHTML=`${title}<span>${sub}</span>`;b.onclick=()=>{selectedType=id;document.querySelectorAll('.choice').forEach(e=>e.classList.remove('selected'));b.classList.add('selected')};$('#choices').append(b)}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function nearest(max=4){let best=null,dist=max;const forward=new THREE.Vector3(0,0,-1).applyQuaternion(camera.quaternion);for(const n of npcs){if(!n.userData.alive)continue;const d=n.position.distanceTo(camera.position);if(d>=dist)continue;const v=n.position.clone().add(new THREE.Vector3(0,1.3,0)).sub(camera.position).normalize();if(v.dot(forward)>.28){best=n;dist=d}}return best}
function impactLine(a,b,color=0xe6d482){const geo=new THREE.BufferGeometry().setFromPoints([a,b]);const line=new THREE.Line(geo,new THREE.LineBasicMaterial({color,transparent:true,opacity:.85}));scene.add(line);effects.push({object:line,life:.12})}
function burst(pos,color=0xa8342b,count=9){for(let i=0;i<count;i++){const m=new THREE.Mesh(new THREE.IcosahedronGeometry(.07+Math.random()*.09,0),mat(color));m.position.copy(pos);scene.add(m);effects.push({object:m,life:.55+Math.random()*.5,velocity:new THREE.Vector3((Math.random()-.5)*3,Math.random()*3,(Math.random()-.5)*3)})}}
function partBreak(n,part){if(n.userData.broken?.has(part))return;if(!n.userData.broken)n.userData.broken=new Set();n.userData.broken.add(part);const target=part==='head'?n.userData.head:part==='torso'?n.userData.torso:null;if(target){target.visible=false;burst(n.localToWorld(target.position.clone()),part==='head'?0x832a2b:0x632223,part==='head'?13:18)}if(part==='torso'){n.userData.alive=false;killNpc(n);return}toast(part==='head'?'Head impact':'Limb damaged')}
function killNpc(n){if(!n.userData.alive&&n.userData.dead)return;n.userData.alive=false;n.userData.dead=true;n.userData.ragdoll=true;n.userData.speed=0;burst(n.position.clone().add(new THREE.Vector3(0,1.2,0)),n.userData.type==='zombie'?0x58674e:0x8e2222,12);n.userData.fallVel=new THREE.Vector3((Math.random()-.5)*2,1.5,(Math.random()-.5)*2);n.userData.decay=35}
function damage(n,amt,kind='melee'){if(!n||!n.userData.alive)return;n.userData.hp-=amt;const headHit=kind==='melee'&&Math.random()<.54;if(headHit)partBreak(n,'head');else if(kind==='shot'&&Math.random()<.2)partBreak(n,['arm','leg'][Math.floor(Math.random()*2)]);if(n.userData.hp<=0)killNpc(n)}
function attack(){if(!started)return;const now=performance.now();if(now-lastAttack<300)return;lastAttack=now;const target=nearest(weapon==='fists'?2.8:65);if(weapon==='fists'||weapon==='bat'){if(!target){toast('No target in reach');return}const p=target.position.clone().add(new THREE.Vector3(0,1.4,0));burst(p,0xb54434,6);damage(target,weapon==='bat'?70:45,'melee');target.userData.fallVel=new THREE.Vector3(0,1.5,0)}else{if(ammo<=0){toast('Magazine empty · press R to cycle');return}ammo--;$('#weaponName small').textContent=`${ammo} ROUNDS`;const from=camera.position.clone(),to=target?target.position.clone().add(new THREE.Vector3(0,1.3,0)):from.clone().add(new THREE.Vector3(0,0,-1).applyQuaternion(camera.quaternion).multiplyScalar(44));impactLine(from,to,0xffd989);if(target){damage(target,weapon==='shotgun'?100:48,'shot');burst(to,0xa8342b,5)}}}
function pickup(){if(!started)return;let best=null,d=2.8;for(const p of props){const dist=p.position.distanceTo(camera.position);if(dist<d){best=p;d=dist}}if(best){weapon=best.userData.type;ammo=weapon==='shotgun'?6:weapon==='pistol'?12:0;scene.remove(best);props.splice(props.indexOf(best),1);showWeapon();toast(`${weapon} picked up`)}else if(weapon!=='fists'){weapon='fists';ammo=0;showWeapon();toast('Dropped weapon')}else toast('No weapon nearby')}
function showWeapon(){$('#weaponName').innerHTML=`${weapon.toUpperCase()}<small>${weapon==='fists'?'UNARMED':weapon==='bat'?'MELEE':`${ammo} ROUNDS`}</small>`}
