function spawn(type=selectedType){if(mode==='arena'){toast('Spawning disabled in arena');return}if(npcs.length>=14){toast('Subject limit reached · clear a few first');return}const f=new THREE.Vector3(0,0,-1).applyQuaternion(camera.quaternion);const p=camera.position.clone().add(f.multiplyScalar(5));p.y=0;const n=makeCharacter(type,p);if(type==='zombie')n.userData.speed=1.3;$('#count').textContent=npcs.length;toast(`${type} arrived`)}
