$('#startBtn').onclick=()=>{started=true;$('#intro').style.display='none';setMode($('#introMode').value);renderer.domElement.requestPointerLock?.();toast(mode==='arena'?'Survive the zombie arena':'Explore Deadwater Island')};
window.addEventListener('keydown',e=>{keys[e.code]=true;if(e.code==='KeyG')$('#spawnBtn').click();if(e.code==='KeyQ')pickup();if(e.code==='KeyE')grab();if(e.code==='KeyR')$('#weaponBtn').click();if(e.code==='Space'){e.preventDefault();attack()}});window.addEventListener('keyup',e=>keys[e.code]=false);
renderer.domElement.addEventListener('click',()=>{if(started&&document.pointerLockElement!==renderer.domElement&&innerWidth>700)renderer.domElement.requestPointerLock?.()});document.addEventListener('mousemove',e=>{if(document.pointerLockElement===renderer.domElement){yaw-=e.movementX*.0022;pitch-=e.movementY*.0022;pitch=Math.max(-1.35,Math.min(1.35,pitch))}});
renderer.domElement.addEventListener('pointerdown',e=>{if(innerWidth<=700&&started&&e.pointerType==='touch'){if(e.clientX>innerWidth*.45){attack();return}renderer.domElement.setPointerCapture(e.pointerId);renderer.userDataTouch={x:e.clientX,y:e.clientY}}});renderer.domElement.addEventListener('pointermove',e=>{if(renderer.userDataTouch){yaw-=(e.clientX-renderer.userDataTouch.x)*.006;pitch=Math.max(-1.2,Math.min(1.2,pitch-(e.clientY-renderer.userDataTouch.y)*.006));renderer.userDataTouch={x:e.clientX,y:e.clientY}}});renderer.domElement.addEventListener('pointerup',()=>renderer.userDataTouch=null);
$('#mobileAttack').onclick=attack;$('#mobileGrab').onclick=grab;document.querySelectorAll('[data-move]').forEach(b=>{const code={forward:'KeyW',back:'KeyS',left:'KeyA',right:'KeyD'}[b.dataset.move];b.onpointerdown=e=>{e.preventDefault();keys[code]=true};b.onpointerup=b.onpointerleave=()=>keys[code]=false});

