 function resetMap(){mapObjects.forEach(o=>scene.remove(o));mapObjects=[];map=$('#mapSelect').value;scene.background.set(map==='island'?0x9bb9bb:map==='yard'?0xb4a58c:0x829890);scene.fog=new THREE.Fog(scene.background,55,180);const before=new Set(scene.children);if(map==='island')addMansion();else addOtherMap();for(let i=0;i<35;i++){let x=(Math.random()-.5)*82,z=(Math.random()-.5)*82;if(Math.hypot(x,z)>25)tree(x,z,.65+Math.random()*.55)}mapObjects=scene.children.filter(o=>!before.has(o))}

