20:function makeCharacter(type,pos){const g=new THREE.Group();g.position.copy(pos);g.userData={type,hp:type==='zombie'?100:110,alive:true,ragdoll:false,parts:[],speed:type==='zombie'?1.5:0,walk:Math.random()*6};const frontier=type==='frontier',police=type==='police',zombie=type==='zombie';const skin=mat(frontier?0x65402f:police?0xc99d78:zombie?0x789078:0xb98d6a),cloth=mat(frontier?0x9a7046:police?0x273b4d:zombie?0x535f4c:0x69716a),pants=mat(frontier?0x343b36:police?0x263344:zombie?0x393e35:0x3e4843);g.userData.materials={skin,cloth,pants};const torso=box(g,0,1.22,0,.72,.92,.4,cloth);torso.userData.part='torso';const head=new THREE.Mesh(new THREE.SphereGeometry(.28,12,10),skin);head.position.set(0,1.95,0);head.castShadow=true;head.userData.part='head';g.add(head);box(g,0,1.61,0,.22,.12,.25,skin);const limbs=[];for(const side of [-1,1]){const leg=new THREE.Group();leg.position.set(side*.2,.78,0);g.add(leg);box(leg,0,-.31,0,.24,.68,.28,pants).userData.part='leg';box(leg,0,-.66,.08,.28,.16,.42,M.dark).userData.part='leg';limbs.push(leg);const arm=new THREE.Group();arm.position.set(side*.48,1.46,0);g.add(arm);box(arm,0,-.31,0,.22,.66,.24,cloth).userData.part='arm';box(arm,0,-.67,0,.2,.16,.2,skin).userData.part='arm';limbs.push(arm)}g.userData.limbs=limbs;if(frontier){const band=box(g,0,2.13,0,.59,.12,.59,mat([0xa33934,0xd4a638,0x387c91,0x6d4d91][Math.floor(Math.random()*4)]));band.userData.part='bandana';box(g,0,1.3,-.25,.78,.28,.08,mat(0x684d34))}if(police){box(g,0,1.22,.22,.16,.22,.08,M.yellow);const equip=Math.random()<.5?'pistol':'shotgun';g.userData.gear=equip;makeWeaponMesh(g,equip,.3,1.35,.23)}if(zombie){const gash=box(g,.11,1.87,.23,.14,.05,.03,M.blood);gash.rotation.z=-.4;box(g,-.13,1.15,.22,.19,.12,.05,M.blood)}if(!frontier&&!police&&!zombie)box(g,0,1.23,.23,.13,.2,.07,M.white);g.userData.limbs=limbs;g.userData.head=head;g.userData.torso=torso;group.add(g);npcs.push(g);return g}
21:function makeWeaponMesh(parent,type,x,y,z){const g=new THREE.Group();g.position.set(x,y,z);const shotgun=type==='shotgun';box(g,0,0,0,shotgun?.12:.23,.12,shotgun?.72:.3,M.metal);box(g,0,-.11,.02,.1,.22,.14,M.dark);parent.add(g);return g}
23:function addPickup(x,z,type){const g=new THREE.Group();g.position.set(x,.55,z);const color=type==='shotgun'?0xd2bd6d:type==='bat'?0x9b6b42:0x9cb6ad;const body=box(g,0,0,0,type==='shotgun'?.14:.24,.12,type==='shotgun'?.85:.32,mat(color,.35,.4));if(type==='pistol')box(g,0,-.12,.03,.1,.2,.13,M.dark);g.userData={pickup:true,type,phase:Math.random()*6};scene.add(g);props.push(g)}

