content.text:
26:function setMode(m){mode=m;$('#modeRead').textContent=m.toUpperCase();$('#spawnBtn').disabled=m==='arena';$('#spawnBtn').style.opacity=m==='arena'?'.35':'1';if(m==='arena'){npcs.splice(0,npcs.length,...npcs.filter(n=>{group.remove(n);return false}));makeZombieWave(7);toast('Arena live · zombies incoming')}else{npcs.forEach(n=>group.remove(n));npcs.length=0;health=100}}
33:function partBreak(n,part){if(n.userData.broken?.has(part))return;if(!n.userData.broken)n.userData.broken=new Set();n.userData.broken.add(part);const target=part==='head'?n.userData.head:part==='torso'?n.userData.torso:null;if(target){target.visible=false;burst(n.localToWorld(target.position.clone()),part==='head'?0x832a2b:0x632223,part==='head'?13:18)}if(part==='torso'){n.userData.alive=false;killNpc(n);return}toast(part==='head'?'Head impact':'Limb damaged')}
34:function killNpc(n){if(!n.userData.alive&&n.userData.dead)return;n.userData.alive=false;n.userData.dead=true;n.userData.ragdoll=true;n.userData.speed=0;burst(n.position.clone().add(new THREE.Vector3(0,1.2,0)),n.userData.type==='zombie'?0x58674e:0x8e2222,12);n.userData.fallVel=new THREE.Vector3((Math.random()-.5)*2,1.5,(Math.random()-.5)*2);n.userData.decay=35}
35:function damage(n,amt,kind='melee'){if(!n||!n.userData.alive)return;n.userData.hp-=amt;const headHit=kind==='melee'&&Math.random()<.54;if(headHit)partBreak(n,'head');else if(kind==='shot'&&Math.random()<.2)partBreak(n,['arm','leg'][Math.floor(Math.random()*2)]);if(n.userData.hp<=0)killNpc(n)}
36:function attack(){if(!started)return;const now=performance.now();if(now-lastAttack<300)return;lastAttack=now;const target=nearest(weapon==='fists'?2.8:65);if(weapon==='fists'||weapon==='bat'){if(!target){toast('No target in reach');return}const p=target.position.clone().add(new THREE.Vector3(0,1.4,0));burst(p,0xb54434,6);damage(target,weapon==='bat'?70:45,'melee');target.userData.fallVel=new THREE.Vector3(0,1.5,0)}else{if(ammo<=0){toast('Magazine empty · press R to cycle');return}ammo--;$('#weaponName small').textContent=`${ammo} ROUNDS`;const from=camera.position.clone(),to=target?target.position.clone().add(new THREE.Vector3(0,1.3,0)):from.clone().add(new THREE.Vector3(0,0,-1).applyQuaternion(camera.quaternion).multiplyScalar(44));impactLine(from,to,0xffd989);if(target){damage(target,weapon==='shotgun'?100:48,'shot');burst(to,0xa8342b,5)}}}
37:function pickup(){if(!started)return;let best=null,d=2.8;for(const p of props){const dist=p.position.distanceTo(camera.position);if(dist<d){best=p;d=dist}}if(best){weapon=best.userData.type;ammo=weapon==='shotgun'?6:weapon==='pistol'?12:0;scene.remove(best);props.splice(props.indexOf(best),1);showWeapon();toast(`${weapon} picked up`)}else if(weapon!=='fists'){weapon='fists';ammo=0;showWeapon();toast('Dropped weapon')}else toast('No weapon nearby')}
39:function grab(){if(grabbed){grabbed.userData.ragdoll=false;grabbed.userData.held=false;grabbed=null;$('#grabBtn').classList.remove('active');toast('Released');return}const n=nearest(3);if(!n){toast('Move closer to a subject');return}grabbed=n;n.userData.ragdoll=true;n.userData.held=true;n.userData.fallVel=new THREE.Vector3();$('#grabBtn').classList.add('active');toast('Subject grabbed · ragdoll enabled')}
40:function spawn(type=selectedType){if(mode==='arena'){toast('Spawning disabled in arena');return}if(npcs.length>=14){toast('Subject limit reached · clear a few first');return}const f=new THREE.Vector3(0,0,-1).applyQuaternion(camera.quaternion);const p=camera.position.clone().add(f.multiplyScalar(5));p.y=0;const n=makeCharacter(type,p);if(type==='zombie')n.userData.speed=1.3;$('#count').textContent=npcs.length;toast(`${type} arrived`)}
41:$('#spawnBtn').onclick=()=>{if(mode==='arena')return;if(document.pointerLockElement)document.exitPointerLock();$('#spawnMenu').classList.toggle('open')};$('#confirmSpawn').onclick=()=>{spawn();$('#spawnMenu').classList.remove('open')};$('#attackBtn').onclick=attack;$('#pickupBtn').onclick=pickup;$('#grabBtn').onclick=grab;$('#weaponBtn').onclick=()=>{weapon=weapon==='fists'?'bat':weapon==='bat'?'pistol':weapon==='pistol'?'shotgun':'fists';ammo=weapon==='shotgun'?6:weapon==='pistol'?12:0;showWeapon()};$('#mapSelect').onchange=()=>{npcs.forEach(n=>group.remove(n));npcs.length=0;resetMap();toast('Environment changed')};$('#modeSelect').onchange=e=>setMode(e.target.value);
